package com.nexamart.backend.api;import com.nexamart.backend.api.ApiModels.*;import com.nexamart.backend.service.CatalogService;import org.springframework.web.bind.annotation.*;import org.springframework.http.*;import java.util.*;
@RestController @RequestMapping("/api/v1/catalog")public class CatalogController{final CatalogService s;final com.nexamart.backend.repository.ProductImageRepository images;public CatalogController(CatalogService s,com.nexamart.backend.repository.ProductImageRepository images){this.s=s;this.images=images;}@GetMapping("/categories")PageResponse<CategoryResponse> categories(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int pageSize,@RequestParam(required=false)String search,@RequestParam(required=false)Boolean active){return s.categories(page,pageSize,search,active);}@GetMapping("/products/{productId}/image")ResponseEntity<byte[]> primaryImage(@PathVariable Long productId){var i=images.findByProductIdOrderBySortOrderAscIdAsc(productId).stream().findFirst().orElseThrow(()->new com.nexamart.backend.exception.ApiException(HttpStatus.NOT_FOUND,"Product image not found."));return ResponseEntity.ok().contentType(MediaType.parseMediaType(i.getContentType())).cacheControl(CacheControl.maxAge(java.time.Duration.ofDays(7)).cachePublic()).body(i.getImageData());}@GetMapping("/products/{productId}/images/{imageId}")ResponseEntity<byte[]> image(@PathVariable Long productId,@PathVariable Long imageId){var i=images.findById(imageId).orElseThrow(()->new com.nexamart.backend.exception.ApiException(HttpStatus.NOT_FOUND,"Product image not found."));if(!i.getProduct().getId().equals(productId))throw new com.nexamart.backend.exception.ApiException(HttpStatus.NOT_FOUND,"Product image not found.");return ResponseEntity.ok().contentType(MediaType.parseMediaType(i.getContentType())).cacheControl(CacheControl.maxAge(java.time.Duration.ofDays(7)).cachePublic()).body(i.getImageData());}@GetMapping("/products")PageResponse<ProductResponse> products(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int pageSize,@RequestParam(required=false)String search,@RequestParam(required=false)Boolean active,@RequestParam(required=false)Long categoryId){return s.products(page,pageSize,search,active,null,categoryId,"NAME_A_Z");}}
